package com.luckypenny;

import java.lang.reflect.Method;
import java.util.Properties;
import net.runelite.client.RuneLite;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LuckyPennyPluginLauncher
{
    public static void main(String[] args) throws Exception
    {
        // Development-only title; never included in the distributed plugin JAR.
        Method properties = RuneLiteProperties.class.getDeclaredMethod("getProperties");
        properties.setAccessible(true);
        ((Properties) properties.invoke(null)).setProperty("runelite.title", "Game Chat Filter Exceptions TEST");
        ExternalPluginManager.loadBuiltin(LuckyPennyPlugin.class);
        RuneLite.main(args);
    }
}

package com.luckypenny;

import java.lang.reflect.Field;
import java.util.Collections;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class LuckyPennyPluginTest
{
    // Wording verified against the installed Lucky Penny tracker's pattern.
    private static final String MESSAGE = "<col=ff0000>Ghommal's luck saves a charge on your toxic blowpipe.</col>";
    private Client client;
    private ClientThread thread;
    private ChatLineBuffer buffer;
    private MessageNode original;
    private MessageNode replacement;
    private LuckyPennyPlugin plugin;
    private LuckyPennyConfig config;

    @Before
    public void setUp() throws Exception
    {
        client = mock(Client.class);
        thread = mock(ClientThread.class);
        buffer = mock(ChatLineBuffer.class);
        original = mock(MessageNode.class);
        replacement = mock(MessageNode.class);
        plugin = new LuckyPennyPlugin();
        config = mock(LuckyPennyConfig.class, CALLS_REAL_METHODS);
        inject("config", config);
        inject("client", client);
        inject("clientThread", thread);
        when(original.getId()).thenReturn(42);
        when(original.getValue()).thenReturn(MESSAGE);
        when(buffer.getLines()).thenReturn(new MessageNode[]{original});
        when(client.getChatLineMap()).thenReturn(Collections.singletonMap(ChatMessageType.SPAM.getType(), buffer));
        when(client.addChatMessage(any(), anyString(), anyString(), any(), anyBoolean())).thenReturn(replacement);
        plugin.startUp();
    }

    private void inject(String name, Object value) throws Exception
    {
        Field field = LuckyPennyPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }

    private ChatMessage event(ChatMessageType type)
    {
        return new ChatMessage(original, type, "", MESSAGE, null, 1234);
    }

    private Runnable pending()
    {
        ArgumentCaptor<Runnable> callback = ArgumentCaptor.forClass(Runnable.class);
        verify(thread).invokeLater(callback.capture());
        return callback.getValue();
    }

    @Test
    public void preservesTextAndTimestampAndRemovesDuplicate()
    {
        plugin.onChatMessage(event(ChatMessageType.SPAM));
        verifyNoInteractions(replacement);
        pending().run();
        verify(client).addChatMessage(ChatMessageType.GAMEMESSAGE, "", MESSAGE, null, false);
        verify(replacement).setTimestamp(1234);
        verify(buffer).removeMessageNode(original);
        verify(client).refreshChat();
    }

    @Test
    public void neverDuplicatesNormalMessagesOrPlayerChat()
    {
        for (ChatMessageType type : ChatMessageType.values())
        {
            if (type != ChatMessageType.SPAM)
            {
                plugin.onChatMessage(event(type));
            }
        }
        verifyNoInteractions(thread, client);
    }

    @Test
    public void ignoresUnrelatedSpam()
    {
        ChatMessage event = event(ChatMessageType.SPAM);
        event.setMessage("Your weapon has run out of charges.");
        plugin.onChatMessage(event);
        verifyNoInteractions(thread, client);
    }

    @Test
    public void cancelledWhenDisabledAndReenabled() throws Exception
    {
        plugin.onChatMessage(event(ChatMessageType.SPAM));
        plugin.shutDown();
        plugin.startUp();
        pending().run();
        verifyNoInteractions(client);
    }

    @Test
    public void skipsReusedNodes()
    {
        plugin.onChatMessage(event(ChatMessageType.SPAM));
        when(original.getId()).thenReturn(43);
        pending().run();
        verify(client, never()).addChatMessage(any(), anyString(), anyString(), any(), anyBoolean());
        verify(buffer, never()).removeMessageNode(any());
    }

    @Test
    public void skipsClearedChat()
    {
        plugin.onChatMessage(event(ChatMessageType.SPAM));
        when(buffer.getLines()).thenReturn(new MessageNode[0]);
        pending().run();
        verify(client, never()).addChatMessage(any(), anyString(), anyString(), any(), anyBoolean());
    }

    @Test
    public void togglesAreIndependent()
    {
        String slaughter = "<col=ff0000>Your bracelet of slaughter prevents your slayer count decreasing.</col>";
        String expeditious = "Your expeditious bracelet helps you progress your slayer task faster.";
        assertTrue(plugin.shouldUnfilter(MESSAGE));
        assertFalse(plugin.shouldUnfilter(slaughter));
        assertFalse(plugin.shouldUnfilter(expeditious));

        when(config.showLuckyPenny()).thenReturn(false);
        when(config.showSlaughter()).thenReturn(true);
        assertFalse(plugin.shouldUnfilter(MESSAGE));
        assertTrue(plugin.shouldUnfilter(slaughter));
        assertFalse(plugin.shouldUnfilter(expeditious));

        when(config.showSlaughter()).thenReturn(false);
        when(config.showExpeditious()).thenReturn(true);
        assertFalse(plugin.shouldUnfilter(slaughter));
        assertTrue(plugin.shouldUnfilter(expeditious));
    }

    @Test
    public void ignoresBraceletBreaksChecksAndUnrelatedText()
    {
        when(config.showSlaughter()).thenReturn(true);
        when(config.showExpeditious()).thenReturn(true);
        assertFalse(plugin.shouldUnfilter(null));
        assertFalse(plugin.shouldUnfilter("Your bracelet of slaughter has shattered."));
        assertFalse(plugin.shouldUnfilter("Your expeditious bracelet has shattered."));
        assertFalse(plugin.shouldUnfilter("Your bracelet of slaughter has 20 charges left."));
        assertFalse(plugin.shouldUnfilter("Your expeditious bracelet has 20 charges left."));
        assertFalse(plugin.shouldUnfilter("Someone says: Your expeditious bracelet helps you progress your slayer task faster."));
    }

    @Test
    public void preservesBothBraceletProcsWithoutRepostingEvents()
    {
        when(config.showSlaughter()).thenReturn(true);
        when(config.showExpeditious()).thenReturn(true);
        String[] messages = {
            "<col=ff0000>Your bracelet of slaughter prevents your slayer count decreasing. It has 29 charges left.</col>",
            "Your expeditious bracelet helps you progress your slayer task faster. It has 1 charge left."
        };
        for (String message : messages)
        {
            clearInvocations(thread, client, replacement, buffer);
            when(original.getValue()).thenReturn(message);
            plugin.onChatMessage(new ChatMessage(original, ChatMessageType.SPAM, "", message, null, 1234));
            pending().run();
            verify(client).addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null, false);
            verify(replacement).setTimestamp(1234);
            verify(buffer).removeMessageNode(original);
            verify(client).refreshChat();
        }
    }

    @Test
    public void braceletOptionsNeverPromotePlayerOrNormalChat()
    {
        when(config.showExpeditious()).thenReturn(true);
        when(config.showSlaughter()).thenReturn(true);
        for (ChatMessageType type : ChatMessageType.values())
        {
            if (type != ChatMessageType.SPAM)
            {
                plugin.onChatMessage(new ChatMessage(original, type, "",
                    "Your expeditious bracelet helps you progress your slayer task faster.", null, 1234));
                plugin.onChatMessage(new ChatMessage(original, type, "",
                    "Your bracelet of slaughter prevents your slayer count decreasing.", null, 1234));
            }
        }
        verifyNoInteractions(thread, client);
    }

    @Test
    public void cancelsPendingMessageWhenOptionTurnedOff()
    {
        plugin.onChatMessage(event(ChatMessageType.SPAM));
        when(config.showLuckyPenny()).thenReturn(false);
        pending().run();
        verifyNoInteractions(client);
    }

    @Test
    public void matchesOnlyPennyChargeSavingText()
    {
        assertTrue(LuckyPennyPlugin.isPennySave(MESSAGE));
        assertTrue(LuckyPennyPlugin.isPennySave("Ghommal's luck saves a charge on your scythe of vitur."));
        assertTrue(LuckyPennyPlugin.isPennySave("GHOMMAL'S LUCK SAVES A CHARGE ON YOUR amulet of blood fury."));
        assertFalse(LuckyPennyPlugin.isPennySave("Ghommal's luck saves a charge on your ."));
        assertFalse(LuckyPennyPlugin.isPennySave(null));
        assertFalse(LuckyPennyPlugin.isPennySave("You consume Ghommal's lucky penny."));
        assertFalse(LuckyPennyPlugin.isPennySave("Your celestial signet saves a charge."));
        assertFalse(LuckyPennyPlugin.isPennySave("Your weapon has 100 charges."));
    }
}

package com.luckypenny;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.Locale;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@PluginDescriptor(
    name = "Game Chat Filter Exceptions",
    description = "Show lucky penny saves and optional Slayer bracelet procs while keeping game chat filtered",
    tags = {"ghommal", "lucky", "penny", "charges", "chat", "filtered", "slaughter", "expeditious", "bracelet"}
)
public class LuckyPennyPlugin extends Plugin
{
    private static final Pattern SAVE_MESSAGE = Pattern.compile("^ghommal's luck saves a charge on your .+\\.$");

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private LuckyPennyConfig config;

    private boolean active;
    private int generation;

    @Provides
    LuckyPennyConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(LuckyPennyConfig.class);
    }

    @Override
    protected void startUp()
    {
        active = true;
        generation++;
    }

    @Override
    protected void shutDown()
    {
        active = false;
        generation++;
    }

    static boolean isPennySave(String message)
    {
        if (message == null)
        {
            return false;
        }
        String plain = Text.removeTags(message).toLowerCase(Locale.ROOT);
        return SAVE_MESSAGE.matcher(plain).matches();
    }

    boolean shouldUnfilter(String message)
    {
        if (message == null)
        {
            return false;
        }
        String plain = Text.removeTags(message).toLowerCase(Locale.ROOT);
        return (config.showLuckyPenny() && isPennySave(message))
            || (config.showSlaughter() && plain.startsWith("your bracelet of slaughter prevents your slayer "))
            || (config.showExpeditious() && plain.startsWith("your expeditious bracelet helps you progress your "));
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        // Normal game messages are already visible. Restricting this to SPAM also
        // prevents recursion and prevents players from spoofing a notification.
        if (!active || event.getType() != ChatMessageType.SPAM || !shouldUnfilter(event.getMessage()))
        {
            return;
        }

        MessageNode original = event.getMessageNode();
        if (original == null)
        {
            return;
        }
        int id = original.getId();
        String message = event.getMessage();
        String name = event.getName() == null ? "" : event.getName();
        String sender = event.getSender();
        int timestamp = event.getTimestamp();
        int scheduledGeneration = generation;

        // Wait until the current message event has finished for every subscriber.
        clientThread.invokeLater(() ->
        {
            if (!active || generation != scheduledGeneration || !shouldUnfilter(message))
            {
                return;
            }
            ChatLineBuffer buffer = client.getChatLineMap().get(ChatMessageType.SPAM.getType());
            // Nodes may be cleared or reused before this callback runs.
            if (buffer == null || original.getId() != id
                || !message.equals(original.getValue())
                || Arrays.stream(buffer.getLines()).noneMatch(node -> node == original))
            {
                return;
            }
            // Other plugins already received the original event; do not count the
            // same save or bracelet proc again in a tracker.
            MessageNode replacement = client.addChatMessage(ChatMessageType.GAMEMESSAGE, name, message, sender, false);
            replacement.setTimestamp(timestamp);
            buffer.removeMessageNode(original);
            client.refreshChat();
        });
    }
}

package com.luckypenny;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("luckypennyunfiltered")
public interface LuckyPennyConfig extends Config
{
    @ConfigItem(
        keyName = "showLuckyPenny",
        name = "Lucky penny saves",
        description = "Show Ghommal's lucky-penny charge saves with Game chat filtered",
        position = 0
    )
    default boolean showLuckyPenny()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showSlaughter",
        name = "Slaughter bracelet procs",
        description = "Show when a bracelet of slaughter prevents Slayer task progress",
        position = 1
    )
    default boolean showSlaughter()
    {
        return false;
    }

    @ConfigItem(
        keyName = "showExpeditious",
        name = "Expeditious bracelet procs",
        description = "Show when an expeditious bracelet grants extra Slayer task progress",
        position = 2
    )
    default boolean showExpeditious()
    {
        return false;
    }
}
